```apex
public class LogPurgeJob implements Schedulable {

    public LogPurgeJob() {
    }

    public static Id scheduleNightly() {
        String cronExp = '0 0 2 * * ?';
        String jobName = 'Log purge (nightly)';
        return System.schedule(jobName, cronExp, new LogPurgeJob());
    }

    public void execute(SchedulableContext ctx) {
        deleteOldLogs();
    }

    private static void deleteOldLogs() {
        // Delete ERROR logs older than 180 days
        List<FB_Integration_Log__c> errorLogsToDelete = [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE Level__c = 'ERROR'
              AND CreatedDate < :DateTime.now().addDays(-180)
        ];

        if (!errorLogsToDelete.isEmpty()) {
            delete errorLogsToDelete;
        }

        // Delete non-ERROR logs older than 30 days
        // Note: Level__c = 'ERROR' is already handled above.
        // We need to delete logs where Level__c is NOT 'ERROR' OR Level__c is NULL
        // AND CreatedDate < 30 days ago.

        DateTime cutoffDate = DateTime.now().addDays(-30);

        List<FB_Integration_Log__c> logsToDelete = [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE (Level__c != 'ERROR' OR Level__c = NULL)
              AND CreatedDate < :cutoffDate
        ];

        if (!logsToDelete.isEmpty()) {
            delete logsToDelete;
        }
    }
}
