public class Opportunities extends fflib_SObjectDomain
{
    public class Constructor implements fflib_SObjectDomain.IConstructable
    {
        public fflib_SObjectDomain construct(List<SObject> records)
        {
            return new Opportunities(records);
        }
    }

    public Opportunities(List<Opportunity> records)
    {
        super(records);
    }

    public override void onValidate()
    {
        for (Opportunity record : (List<Opportunity>)sObjects)
        {
            // Rule 1: Amount cannot be negative on insert and update
            if (record.Amount != null && record.Amount < 0)
            {
                error('Amount cannot be negative.', record, Opportunity.Amount);
            }

            // Rule 2: Amount cannot change on a won opportunity (only on update)
            // Condition: 
            // 1. The record is being updated (exists in old map)
            // 2. The opportunity was already Closed Won before the update
            // 3. The Amount is changing
            // Note: Closing an opportunity as won and changing its amount in the same update is allowed.
            // This means we only block if it was *already* Closed Won and we are trying to change the amount.

            Opportunity oldRecord = (Opportunity)oldMap.get(record.Id);
            if (oldRecord != null)
            {
                // Check if the previous state was Closed Won
                Boolean wasClosedWon = (oldRecord.StageName == 'Closed Won');

                // Check if the amount is changing
                Boolean amountChanging = (record.Amount != oldRecord.Amount);
                // Handle nulls correctly: if both are null, they are equal. If one is null and other is not, they differ.
                if (record.Amount == null && oldRecord.Amount == null) {
                    amountChanging = false;
                } else if (record.Amount == null || oldRecord.Amount == null) {
                    amountChanging = true;
                } else {
                    amountChanging = !record.Amount.equals(oldRecord.Amount);
                }

                if (wasClosedWon && amountChanging)
                {
                    error('Amount cannot change on a won opportunity.', record, Opportunity.Amount);
                }
            }
        }
    }
}
