```apex
public class ContactPhoneCleanup {
    /**
     * Normalizes phone numbers for a list of contacts.
     * 
     * - Cleans phone numbers to contain only digits and a leading plus sign.
     * - Updates contacts in bulk.
     * - Returns a map of Id to first error message for any contacts that fail to save.
     * 
     * @param contactIds List of Contact Ids to process
     * @return Map of Contact Id to first error message for failed updates. Empty if all succeed.
     */
    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        Map<Id, String> errorMap = new Map<Id, String>();

        if (contactIds == null || contactIds.isEmpty()) {
            return errorMap;
        }

        // Query only the necessary fields for the contacts in the input list
        List<Contact> contacts = [
            SELECT Id, Phone 
            FROM Contact 
            WHERE Id IN :contactIds
        ];

        List<Contact> contactsToUpdate = new List<Contact>();

        for (Contact c : contacts) {
            if (c.Phone != null && !c.Phone.isEmpty()) {
                // Remove any character that is NOT a digit or a plus sign
                c.Phone = c.Phone.replaceAll('[^0-9+]', '');
                contactsToUpdate.add(c);
            }
            // If phone is null or empty, we leave the contact out as per requirement:
            // "contacts without a phone are left out"
        }

        // If there's nothing to update, return empty map
        if (contactsToUpdate.isEmpty()) {
            return errorMap;
        }

        // Save all contacts at once with partial success allowed
        List<Database.SaveResult> saveResults = Database.update(contactsToUpdate, false);

        // Process save results to identify failures
        for (Integer i = 0; i < saveResults.size(); i++) {
            Database.SaveResult result = saveResults[i];
            Contact c = contactsToUpdate[i];

            if (!result.isSuccess()) {
                // Get the first error message
                Database.Error[] errors = result.getErrors();
                if (errors != null && errors.size() > 0) {
                    errorMap.put(c.Id, errors[0].getMessage());
                } else {
                    // Fallback: if no detailed errors, provide a generic message
                    errorMap.put(c.Id, 'Unknown error occurred during update.');
                }
            }
        }

        return errorMap;
    }
}
