public class FollowUpTaskService {
    /**
     * Creates a follow-up task for each provided opportunity ID.
     * If a task cannot be created (e.g., due to validation rules), the opportunity ID
     * is added to the returned set of failed IDs.
     * 
     * @param opportunityIds List of Opportunity IDs to create tasks for.
     * @return Set of Opportunity IDs for which tasks could not be created.
     */
    public static Set<Id> createFollowUps(List<Id> opportunityIds) {
        Set<Id> failedOpportunityIds = new Set<Id>();

        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return failedOpportunityIds;
        }

        for (Id oppId : opportunityIds) {
            // Fetch Opportunity Name and OwnerId to create the task
            // We query only the necessary fields to keep it efficient, 
            // though in a strict 'straightforward' loop without pre-fetching, 
            // we might assume they are known. However, we don't have the 
            // Opportunity objects passed, only IDs. So we must query.
            Opportunity opp = [SELECT Id, Name, OwnerId FROM Opportunity WHERE Id = :oppId LIMIT 1];

            if (opp == null) {
                // If the opportunity doesn't exist, we can't create a task with valid WhatId/OwnerId
                // Technically this is a failure to create.
                failedOpportunityIds.add(oppId);
                continue;
            }

            // Determine OwnerId
            // If the opportunity owner is a Queue, we still assign to it.
            // If the opportunity owner is null (unlikely for valid opps), we might need a fallback,
            // but standard logic assumes OwnerId is present.
            Id targetOwnerId = opp.OwnerId;

            // Create the Task
            Task newTask = new Task();
            newTask.WhatId = oppId;
            newTask.OwnerId = targetOwnerId;
            newTask.Subject = 'Follow up: ' + opp.Name;
            // ActivityDate is today + 7 days
            newTask.ActivityDate = System.today().addDays(7);
            newTask.Status = 'Not Started';
            newTask.Priority = 'Normal';

            try {
                insert newTask;
            } catch (DmlException e) {
                // If the insert fails for any reason (Validation Rule, Required Field, etc.),
                // we do not stop the loop. We record the failure.
                failedOpportunityIds.add(oppId);
            }
        }

        return failedOpportunityIds;
    }
}
```

