public with sharing class AccountCountrySync {

    /**
     * Handles the logic to sync Account BillingCountry to Contact MailingCountry.
     * 
     * Logic:
     * 1. Identify Accounts where BillingCountry has changed.
     * 2. Query Contacts associated with those Accounts.
     * 3. Update MailingCountry for contacts where MailingCountry is blank or matches the previous BillingCountry.
     * 
     * Note: The initial requirement suggested querying ALL contacts in the org.
     * This approach was changed because querying 2.3 million records in a single SOQL statement 
     * in Apex violates the governor limit of 50,000 query rows.
     * Instead, we query only the contacts related to the affected accounts, 
     * which keeps the transaction bulk-safe and within limits.
     */
    public static void handleUpdate() {

        // 1. Identify Accounts with changed BillingCountry
        Map<Id, String> oldBillingCountries = new Map<Id, String>();
        Set<Id> changedAccountIds = new Set<Id>();

        for (Account newAcc : Trigger.new) {
            Account oldAcc = Trigger.oldMap.get(newAcc.Id);

            // Check if BillingCountry is not null and has changed
            if (newAcc.BillingCountry != null && newAcc.BillingCountry != oldAcc.BillingCountry) {
                oldBillingCountries.put(newAcc.Id, oldAcc.BillingCountry);
                changedAccountIds.add(newAcc.Id);
            }
