        // 2. Query Contacts ONLY for the affected accounts
        // This replaces the suggested query for ALL contacts, which is impossible for 2.3M records.
        List<Contact> contactsToProcess = [
            SELECT Id, AccountId, MailingCountry 
            FROM Contact 
            WHERE AccountId IN :changedAccountIds
        ];

        // 3. Process and prepare updates
