    email = '';
    company = '';

    handleChange(event) {
        const field = event.target.dataset.field;
        if (field === 'fullName') {
            this.fullName = event.detail.value;
        } else if (field === 'email') {
            this.email = event.detail.value;
        } else if (field === 'company') {
            this.company = event.detail.value;
