import { LightningElement, api } from 'lwc';

export default class StatusListbox extends LightningElement {
    @api label;
    @api options = [];
    @api value = '';

    activeOptionId = null;

    connectedCallback() {
        this.initActiveOption();
    }

    renderedCallback() {
        // Ensure active option is set after render if not already
        if (!this.activeOptionId) {
            this.initActiveOption();
        }
    }

    initActiveOption() {
        const hasSelection = this.options.some(opt => opt.value === this.value);
        const selectedIndex = hasSelection 
            ? this.options.findIndex(opt => opt.value === this.value) 
            : 0;

        if (this.options.length > 0 && selectedIndex >= 0) {
            this.activeOptionId = `option-${selectedIndex}`;
        } else {
            this.activeOptionId = null;
        }

        // Update aria-activedescendant in the template
        const listbox = this.template.querySelector('[role="listbox"]');
        if (listbox) {
            listbox.setAttribute('aria-activedescendant', this.activeOptionId || '');
        }
    }

    handleKeydown(event) {
        const { key } = event;

        if (['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' '].includes(key)) {
            event.preventDefault();
        } else {
            return;
        }

        const currentIndex = this.getActiveOptionIndex();
        let newIndex = currentIndex;

        switch (key) {
            case 'ArrowDown':
                if (currentIndex < this.options.length - 1) {
                    newIndex = currentIndex + 1;
                }
                break;
            case 'ArrowUp':
                if (currentIndex > 0) {
                    newIndex = currentIndex - 1;
                }
                break;
            case 'Home':
                newIndex = 0;
                break;
            case 'End':
                newIndex = this.options.length - 1;
                break;
            case 'Enter':
            case ' ':
                if (currentIndex >= 0) {
                    this.selectOption(newIndex);
                    return; // Exit after handling selection
                }
                break;
            default:
                break;
        }

        if (['ArrowDown', 'ArrowUp', 'Home', 'End'].includes(key)) {
            this.setActiveOption(newIndex);
        }
    }

    setActiveOption(index) {
        if (index < 0 || index >= this.options.length) {
            return;
        }
        this.activeOptionId = `option-${index}`;
        const listbox = this.template.querySelector('[role="listbox"]');
        if (listbox) {
            listbox.setAttribute('aria-activedescendant', this.activeOptionId);
        }
    }

    getActiveOptionIndex() {
        if (!this.activeOptionId) {
            return -1;
        }
        const match = this.activeOptionId.match(/option-(\d+)/);
        return match ? parseInt(match[1], 10) : -1;
    }

    selectOption(index) {
        if (index < 0 || index >= this.options.length) {
            return;
        }

        const selectedValue = this.options[index].value;

        if (this.value === selectedValue) {
            return; // Already selected, do nothing
        }

        this.value = selectedValue;

        // Dispatch change event
        const changeEvent = new CustomEvent('change', {
            detail: { value: selectedValue },
            bubbles: true,
            composed: true
        });
        this.dispatchEvent(changeEvent);
    }

    handleOptionClick(event) {
        const li = event.target.closest('li');
        if (!li) {
            return;
        }

        const index = parseInt(li.dataset.index, 10);
        this.selectOption(index);
    }
}
