        List<Id> resultIds = new List<Id>();

        if (requests == null || requests.isEmpty()) {
            return resultIds;
        }

        // Validate all requests first
        for (GiftRequest req : requests) {
            validateRequest(req);
        }

        List<npe03__Recurring_Donation__c> recurringDonations = new List<npe03__Recurring_Donation__c>();

        for (GiftRequest req : requests) {
            npe03__Recurring_Donation__c rd = new npe03__Recurring_Donation__c();

            rd.npe03__Contact__c = req.contactId;
            rd.npe03__Amount__c = req.amount;
            rd.npe03__Installments__c = req.installments;
            rd.npe03__StartDate__c = req.startDate;
            rd.npe03__Recurring_Donation_Status__c = 'Active';

            // Map payment method
            if (req.paymentMethod == 'Credit Card') {
                rd.npe03__Payment_Method__c = 'Credit Card';
            } else if (req.paymentMethod == 'ACH') {
                rd.npe03__Payment_Method__c = 'ACH';
            } else if (req.paymentMethod == 'Check') {
                rd.npe03__Payment_Method__c = 'Check';
            } else {
                throw new RecurringGiftException('Invalid payment method: ' + req.paymentMethod);
            }

            // Handle dayOfMonth
            if (req.dayOfMonth == 31) {
                rd.npe03__Day_of_Month__c = 99; // 99 represents last day of month in NPSP
            } else {
                rd.npe03__Day_of_Month__c = req.dayOfMonth;
            }

            recurringDonations.add(rd);
        }

        // Insert all recurring donations in a single DML statement
        insert recurringDonations;

        // Collect IDs in order
        for (Integer i = 0; i < recurringDonations.size(); i++) {
            resultIds.add(recurringDonations[i].Id);
        }

        return resultIds;
    }

    private static void validateRequest(GiftRequest req) {
        if (req.contactId == null) {
            throw new RecurringGiftException('Contact ID cannot be null');
        }
        if (req.amount == null || req.amount <= 0) {
            throw new RecurringGiftException('Amount must be a positive number');
        }
        if (req.dayOfMonth == null || req.dayOfMonth < 1 || req.dayOfMonth > 31) {
            throw new RecurringGiftException('dayOfMonth must be between 1 and 31');
        }
        if (req.startDate == null) {
            throw new RecurringGiftException('Start date cannot be null');
        }
    }
